import{_ as i,C as o,o as r,c as l,a6 as e,E as n}from"./chunks/framework.QQy01QNh.js";const s="/xi-kari-skill/handbook/images/joint-feasibility.svg",b=JSON.parse('{"title":"每件事都做得到，为什么放在一起就做不到","description":"方案共享时段和容量，单独可做不等于能够共同完成。","frontmatter":{"title":"每件事都做得到，为什么放在一起就做不到","description":"方案共享时段和容量，单独可做不等于能够共同完成。"},"headers":[],"relativePath":"concepts/joint-feasibility.md","filePath":"concepts/joint-feasibility.md"}'),c={name:"concepts/joint-feasibility.md"};function h(p,a,_,d,f,u){const t=o("JointExplorer");return r(),l("div",null,[a[0]||(a[0]=e('<h1 id="每件事都做得到-为什么放在一起就做不到" tabindex="-1">每件事都做得到，为什么放在一起就做不到 <a class="header-anchor" href="#每件事都做得到-为什么放在一起就做不到" aria-label="Permalink to &quot;每件事都做得到，为什么放在一起就做不到&quot;">​</a></h1><p>两项任务各自可行，排成同一份计划会发生什么？</p><p><strong>方案共享时段和容量，单独可做不等于能够共同完成。</strong></p><h2 id="从具体情景看区别" tabindex="-1">从具体情景看区别 <a class="header-anchor" href="#从具体情景看区别" aria-label="Permalink to &quot;从具体情景看区别&quot;">​</a></h2><p>原文给出两项单位任务：每项都要占用一个完整时段，而且都必须在第一期结束前完成；第一期的容量却只有1。拿出任何一项单独看，资源都足够，两项同时进入计划，就没有满足原截止时间的排程。将同期容量增加到2可以改变结果；若允许把一项截止时间合法改到第二期，并且第二期有容量1，也可以得到另一种可行安排。</p><p>但保留原来的两个截止时间、只在第二期增加容量，并不能补回已经错过的第一期。这一例子帮助读者把“总资源看起来够”和“资源在要求的位置、时间可用”区分开。它也提醒我们，改变期限是改变条件，不能在事后悄悄换成新的成功标准。</p><figure class="concept-figure"><img src="'+s+'" alt="两项任务争用同一期容量"><figcaption>增加未来容量与合法改变任务期限，是两种不同操作。</figcaption></figure><h2 id="改变条件-看看有什么不同" tabindex="-1">改变条件，看看有什么不同 <a class="header-anchor" href="#改变条件-看看有什么不同" aria-label="Permalink to &quot;改变条件，看看有什么不同&quot;">​</a></h2>',8)),n(t),a[1]||(a[1]=e('<h2 id="回到原文" tabindex="-1">回到原文 <a class="header-anchor" href="#回到原文" aria-label="Permalink to &quot;回到原文&quot;">​</a></h2><blockquote><p>每项单独可做，联合没有可行排程。</p></blockquote><ul><li><a href="/xi-kari-skill/handbook/theory/appendix-c.html#section-c-12">附录C.12 局部成功的三种组合边界</a></li></ul><h2 id="这处区别能说明到哪里" tabindex="-1">这处区别能说明到哪里 <a class="header-anchor" href="#这处区别能说明到哪里" aria-label="Permalink to &quot;这处区别能说明到哪里&quot;">​</a></h2><p>这是由给定约束成立的原文教学例，不认证现实需求或容量。现实中的加资源、改截止时间和执行安排，还须有相应事实依据与权限。</p><h2 id="接着理解" tabindex="-1">接着理解 <a class="header-anchor" href="#接着理解" aria-label="Permalink to &quot;接着理解&quot;">​</a></h2><ul><li><a href="./responsibility.html">实际做事的人，为什么不等于全部责任人</a></li><li><a href="./chain.html">两段都有效，整条链为什么仍可能无效</a></li></ul>',7))])}const k=i(c,[["render",h]]);export{b as __pageData,k as default};
